TENANT_TABLES = ("tenants", "materials", "rfqs", "quotes", "quote_line_items")


def _runtime_role() -> str:
    role = os.environ.get("ZUSCHLAG_APP_ROLE", "zuschlag_app")
    if not re.fullmatch(r"[a-z_][a-z0-9_]{0,62}", role):
        raise ValueError(f"invalid role name {role!r}")
    return role


def _create_tenancy() -> None:
    op.execute("CREATE SCHEMA IF NOT EXISTS app")
    # NULL when unset (or reset to '' at transaction end) => policies match no rows.
    op.execute(
        """
        CREATE FUNCTION app.current_tenant_id() RETURNS uuid
        LANGUAGE sql STABLE PARALLEL SAFE
        AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$
        """
    )
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        # FORCE: the table owner (migrator) is subject to RLS as well.
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"""
            CREATE POLICY tenant_isolation ON {table}
            USING (tenant_id = app.current_tenant_id())
            WITH CHECK (tenant_id = app.current_tenant_id())
            """
        )


def _create_audit_log_guards() -> None:
    op.execute("ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE audit_logs FORCE ROW LEVEL SECURITY")
    # Only SELECT and INSERT policies exist: UPDATE/DELETE match no policy => denied.
    op.execute(
        "CREATE POLICY audit_select ON audit_logs FOR SELECT "
        "USING (tenant_id = app.current_tenant_id())"
    )
    op.execute(
        "CREATE POLICY audit_insert ON audit_logs FOR INSERT "
        "WITH CHECK (tenant_id = app.current_tenant_id())"
    )

    op.execute(
        """
        CREATE FUNCTION app.audit_entry_hash(
            p_prev_hash text, p_seq bigint, p_tenant_id uuid, p_ts timestamptz,
            p_actor_id text, p_action text, p_entity_type text, p_entity_id text,
            p_ip_sha256 text, p_context jsonb
        ) RETURNS text
        LANGUAGE sql STABLE PARALLEL SAFE
        AS $$
          SELECT encode(sha256(convert_to(concat_ws('|',
            p_prev_hash, p_seq::text, p_tenant_id::text,
            to_char(p_ts AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            p_actor_id, p_action, p_entity_type, p_entity_id,
            coalesce(p_ip_sha256, ''), coalesce(p_context::text, '')
          ), 'UTF8')), 'hex')
        $$
        """
    )
    op.execute(
        """
        CREATE FUNCTION app.audit_logs_before_insert() RETURNS trigger
        LANGUAGE plpgsql
        AS $$
        DECLARE
          last_seq  bigint;
          last_hash text;
        BEGIN
          -- Serialise appends per tenant so seq is gap-free and the chain linear.
          PERFORM pg_advisory_xact_lock(hashtextextended('audit_logs:' || NEW.tenant_id::text, 0));
          SELECT a.seq, a.entry_hash INTO last_seq, last_hash
            FROM audit_logs a
           WHERE a.tenant_id = NEW.tenant_id
           ORDER BY a.seq DESC
           LIMIT 1;

          NEW.timestamp_utc := clock_timestamp();   -- server time; client values ignored
          NEW.seq           := coalesce(last_seq, 0) + 1;
          NEW.prev_hash     := coalesce(last_hash, repeat('0', 64));
          NEW.entry_hash    := app.audit_entry_hash(
            NEW.prev_hash, NEW.seq, NEW.tenant_id, NEW.timestamp_utc, NEW.actor_id,
            NEW.action, NEW.entity_type, NEW.entity_id, NEW.ip_sha256, NEW.context);
          RETURN NEW;
        END
        $$
        """
    )
    op.execute(
        """
        CREATE TRIGGER audit_logs_chain BEFORE INSERT ON audit_logs
        FOR EACH ROW EXECUTE FUNCTION app.audit_logs_before_insert()
        """
    )
    op.execute(
        """
        CREATE FUNCTION app.audit_logs_reject_change() RETURNS trigger
        LANGUAGE plpgsql
        AS $$
        BEGIN
          RAISE EXCEPTION 'audit_logs is append-only (GoBD): % is not permitted', TG_OP
            USING ERRCODE = 'insufficient_privilege';
        END
        $$
        """
    )
    op.execute(
        """
        CREATE TRIGGER audit_logs_immutable BEFORE UPDATE OR DELETE ON audit_logs
        FOR EACH ROW EXECUTE FUNCTION app.audit_logs_reject_change()
        """
    )
    op.execute(
        """
        CREATE TRIGGER audit_logs_no_truncate BEFORE TRUNCATE ON audit_logs
        FOR EACH STATEMENT EXECUTE FUNCTION app.audit_logs_reject_change()
        """
    )
    # Returns one row per broken entry; an empty result means the chain verifies.
    op.execute(
        """
        CREATE FUNCTION app.audit_chain_breaks(p_tenant_id uuid)
        RETURNS TABLE (seq bigint, reason text)
        LANGUAGE sql STABLE
        AS $$
          WITH chain AS (
            SELECT a.*,
                   lag(a.entry_hash) OVER (ORDER BY a.seq) AS expected_prev,
                   lag(a.seq)        OVER (ORDER BY a.seq) AS previous_seq
              FROM audit_logs a
             WHERE a.tenant_id = p_tenant_id
          ), checked AS (
            SELECT c.seq,
                   CASE
                     WHEN c.entry_hash <> app.audit_entry_hash(
                            c.prev_hash, c.seq, c.tenant_id, c.timestamp_utc, c.actor_id,
                            c.action, c.entity_type, c.entity_id, c.ip_sha256, c.context)
                       THEN 'entry_hash mismatch'
                     WHEN c.prev_hash <> coalesce(c.expected_prev, repeat('0', 64))
                       THEN 'broken link to previous entry'
                     WHEN c.seq <> coalesce(c.previous_seq, 0) + 1
                       THEN 'sequence gap'
                   END AS reason
              FROM chain c
          )
          SELECT checked.seq, checked.reason FROM checked
           WHERE checked.reason IS NOT NULL
           ORDER BY checked.seq
        $$
        """
    )


def _grant_runtime_role() -> None:
    role = _runtime_role()  # validated identifier, safe to interpolate
    op.execute(
        f"""
        DO $$
        BEGIN
          IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
            GRANT USAGE ON SCHEMA app TO {role};
            GRANT EXECUTE ON FUNCTION app.current_tenant_id() TO {role};
            GRANT EXECUTE ON FUNCTION app.audit_chain_breaks(uuid) TO {role};
            GRANT SELECT, INSERT, UPDATE ON tenants TO {role};
            GRANT SELECT, INSERT, UPDATE, DELETE ON materials, rfqs, quotes, quote_line_items TO {role};
            -- append-only: no UPDATE / DELETE / TRUNCATE
            GRANT SELECT, INSERT ON audit_logs TO {role};
          ELSE
            RAISE WARNING 'role {role} does not exist; grants skipped';
          END IF;
        END
        $$
        """  # noqa: S608
    )
